BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP104-1-29','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考性侵害犯罪防治法陪同偵訊之規定（考試時第15條，現行第18條）。考試時得陪同被害人在場者限於法定代理人、配偶、直系或三親等內旁系血親、家長、家屬、醫師、心理師、輔導人員或社工人員，男朋友不在其列；本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排，現行第18條增列「其信賴之人」經被害人同意後得於偵查或審判時陪同在場，依現行條文選項(B)已非當然不得陪同。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP105-2-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-07-23。本題考性侵害犯罪防治法通報及防治教育之規定（考試時第7條、第8條，現行第9條、第11條）。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排：義務通報人（不含村（里）長）應立即通報、至遲不得超過二十四小時之規定未變（現行第11條）；考試時「主管機關應於二十四小時內進行分級分類處理」已改為應即派員評估被害人需求及提供服務，「各級中小學每學年至少四小時」已改為高級中等以下學校每學期至少二小時，選項(A)(C)(D)於考試時及現行規定下均不正確，選項(B)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP106-1-03','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考性侵害犯罪防治法第8條（現行第11條）：醫事人員、社工人員、教育人員等於執行職務時知有疑似性侵害犯罪情事者，應立即通報，至遲不得超過二十四小時。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排，通報時限未變，選項(B)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP107-1-28','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考性侵害犯罪防治法第14條（現行第10條）：處理性侵害案件之專責人員每年應至少接受性侵害防治專業訓練課程六小時。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排，時數未變，選項(B)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP107-2-10','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考性侵害犯罪防治法被害人保護之規定。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排：主管機關得依被害人申請補助非屬全民健康保險給付範圍之心理復健費用（考試時第19條，現行第28條），選項(D)仍正確；醫療機構不得無故拒絕診療及開立驗傷診斷書（考試時第10條，現行第14條）、被害人得由法定之人於偵查或審判中陪同在場（考試時第15條，現行第18條）之規定亦仍存在，選項(B)(C)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP109-1-31','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-02-15。本題考性侵害犯罪防治法第6條（直轄市、縣（市）性侵害防治中心辦理事項）及第4條（中央主管機關辦理事項）。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排：防治中心事項仍規定於現行第6條（含提供被害人二十四小時緊急救援、協調醫療機構成立醫療小組、提供加害人身心治療輔導或教育等），規劃訂定防治政策及相關法規則為中央主管機關事項（現行第5條），選項(B)仍非防治中心辦理事項。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP109-1-32','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-02-15。本題考性侵害犯罪防治法第15條之1（現行第19條）：兒童或心智障礙之被害人於偵查或審判中，經認有必要時，應由具相關專業人士在場協助詢（訊）問。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排，規定未變，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP109-2-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-08-01。本題考性侵害犯罪防治法第10條（醫療機構不得無故拒絕診療，診療時應有護理人員陪同，現行第14條）、第13條（媒體不得報導被害人身分資訊，現行第16條）及第4條（中央主管機關辦理性侵害事件各項資料之建立、彙整、統計及管理；現行第5條明定包括加害人身心治療、輔導或教育資料）。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排，上開規定仍存在，醫療機構診療時應有護理人員陪同，選項(D)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP111-1-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-02-19。本題考性侵害犯罪防治法第1條（立法目的）、第3條（教育主管機關掌理各級學校性侵害防治教育及被害人子女就學權益）、第4條（中央主管機關研擬防治政策、推展防治教育）及第6條（性侵害防治中心提供被害人二十四小時緊急救援）。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排，分別為現行第1條、第4條、第5條、第6條，內容未實質改變，選項(C)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP111-2-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-07-30。本題考性侵害犯罪防治法第17條（現行第26條）：被害人於審判中因性侵害致身心創傷無法陳述，或因身心壓力無法為完全陳述或拒絕陳述時，其於調查中之陳述經證明具有可信之特別情況且為證明犯罪事實所必要者，得為證據。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排，上開要件未變，選項(A)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP112-1-36','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2023-02-18。本題考性侵害犯罪防治法緩起訴處分確定者之適用及主管機關接獲通報後之處理。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排；考試時新法甫施行一日，本題係依修正前條文命題：修正前第2條規定緩起訴處分確定者除少數條文外適用本法關於加害人之規定，修正前第8條規定主管機關接獲通報應立即進行分級分類處理，至遲不得超過二十四小時。現行條文將「加害人」限於經判決有罪確定之人（第2條），但另規定緩起訴處分確定者應接受身心治療、輔導或教育及辦理登記、報到（第32條、第42條），選項(A)「不得適用任何」相關規定之敘述仍不正確；惟現行第11條改為主管機關接獲通報應即派員評估被害人需求及提供服務，已無分級分類處理及二十四小時之規定，依現行條文選項(D)亦屬錯誤。本題官方答案依修正前條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP112-1-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2023-02-18。本題考性侵害犯罪防治法通報（修正前第8條，現行第11條）、驗傷及採證之同意（修正前第11條，現行第17條）、陪同在場（修正前第15條，現行第18條）及補助（修正前第19條，現行第28條）。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排：修正前後均規定被害人為受監護宣告或未滿十二歲者始應經監護人或法定代理人同意，選項(B)「12歲以上未滿18歲」仍錯誤；現行第11條增列教保服務人員等通報人員、第18條增列被害人信賴之人得經同意陪同，選項(A)(C)所列人員仍屬法定通報或陪同人員，選項(D)之補助項目仍存在。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP112-2-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2023-07-29。本題考性侵害犯罪防治法第4條（主管機關及目的事業主管機關權責：社政主管機關掌理被害人保護、扶助），本條於 2023-02-15 全文修正公布後未再修正，考試時條文與現行條文相同，選項(A)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP112-2-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2023-07-29。本題考性侵害犯罪防治法第18條（陪同在場；被害人為兒童或少年時，除顯無必要者外，主管機關應指派社會工作人員陪同）及第19條（兒童或心智障礙被害人由專業人士協助詢（訊）問，得透過單面鏡等措施為之），兩條於 2023-02-15 全文修正公布後未再修正，考試時條文與現行條文相同，選項(B)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079'),('SP113-1-36','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2024-02-04。本題考性侵害犯罪防治法之性侵害防治教育課程內容。本法於 2023-02-15 全文修正（2023-02-17 施行），條次重新編排；考試時已施行修正後條文，第9條（即現行條文第9條）規定課程應包括他人性自主之尊重、性侵害犯罪之認識、性侵害危機之處理、性侵害防範之技巧及其他與性侵害防治有關之教育。題目①兩性性器官構造與功能、②安全性行為與自我保護性知識、③性別平等之教育為修正前第7條所列課程（修正前第7條另規定學校應運用多元方式進行教學），已不在現行條文之列，依現行條文四個選項均不正確。本題官方答案(D)依修正前條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080079');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>15 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>15 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'b8b9c6db8c251fce13f864258aa59b4e' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_12, count(*) FILTER (WHERE q.legal_status='changed') changed_3, count(*) total_15 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
